<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\Artist; use App\Services\ImageUploadService; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage; use Illuminate\Support\Str;
class ArtistController extends Controller { public function index(){return view('admin.artists.index',['artists'=>Artist::withCount('articles')->orderBy('name')->paginate(30)]);} public function create(){return view('admin.artists.form',['artist'=>new Artist]);} public function store(Request $r,ImageUploadService $i){$d=$this->v($r);$d['slug']=$this->slug($d['name'],$d['slug']??null);if($r->hasFile('image_file'))$d['image']=$i->store($r->file('image_file'),'artists')['path'];$a=Artist::create($d);return redirect()->route('admin.artists.edit',$a)->with('ok','Artist created.');} public function edit(Artist $artist){return view('admin.artists.form',compact('artist'));} public function update(Request $r,Artist $artist,ImageUploadService $i){$d=$this->v($r);$d['slug']=$this->slug($d['name'],$d['slug']??null,$artist->id);if($r->hasFile('image_file')){if($artist->image)Storage::disk('public')->delete($artist->image);$d['image']=$i->store($r->file('image_file'),'artists')['path'];}$artist->update($d);return back()->with('ok','Artist saved.');} public function destroy(Artist $artist){$artist->delete();return back()->with('ok','Artist deleted.');} private function v(Request $r){return $r->validate(['name'=>'required|string|max:255','slug'=>'nullable|string|max:255','bio'=>'nullable|string|max:5000','image_file'=>'nullable|image|max:8192']);} private function slug($name,$input=null,$ignore=null){$b=Str::slug($input?:$name);$s=$b;$n=2;while(Artist::where('slug',$s)->when($ignore,fn($q)=>$q->whereKeyNot($ignore))->exists())$s=$b.'-'.$n++;return $s;} }
